    {root&&<svg className="world-lines" width={WORLD.w} height={WORLD.h}><defs><filter id="soft-glow"><feGaussianBlur stdDeviation="2" result="blur"/><feMerge><feMergeNode in="blur"/><feMergeNode in="SourceGraphic"/></feMerge></filter></defs>{/* The starting reference is a compact anchor, not a sixth card: first-ring lines start here. */}<g className="root-anchor" aria-hidden="true"><circle cx={WORLD.cx} cy={WORLD.cy} r={9}/><text x={WORLD.cx} y={WORLD.cy+30} textAnchor="middle">{root.name.length>28?`${root.name.slice(0,27)}…`:root.name}</text></g>{nodes.map((node,index)=>{const parent=nodes.find(n=>n.id===node.parentId)??(node.parentId==="root"||node.parentId===root.id?{id:root.id,x:WORLD.cx,y:WORLD.cy}:undefined);if(!parent)return null;const mx=(parent.x+node.x)/2,my=(parent.y+node.y)/2,dx=node.x-parent.x,dy=node.y-parent.y,bend=(index%2?1:-1)*.12,d=`M ${parent.x} ${parent.y} Q ${mx-dy*bend} ${my+dx*bend} ${node.x} ${node.y}`,focusId=selected?.id??hoveredId,related=!!focusId&&pathIds.has(node.id),branchId=branchRootId(node,nodes),branchColor=nodeAccents[branchId]||stableAccent(branchId);return <g key={`${node.parentId}-${node.id}`} data-parent-id={parent.id} data-child-id={node.id} className={!focusId?"branch":related?"branch active-branch":"branch muted-branch"} style={{"--branch-color":branchColor} as CSSProperties}><path d={d}/>{related&&<><circle className="edge-end" cx={node.x} cy={node.y} r={5}/><text className="edge-label" x={mx} y={my-10} textAnchor="middle">{node.relation||"Qloo affinity"}</text></>}</g>})}</svg>}
    {!root?<div className="empty-center editorial-home"><span className="hero-eyebrow">Start exploring</span><h1>Start with<br/><em>what you love.</em></h1><div className="home-search-row"><form className="hero-search" onSubmit={submit}><span className="search-glyph">⌕</span><input autoFocus aria-label="What would you like to explore?" autoComplete="off" enterKeyHint="search" value={input} onChange={event=>setInput(event.target.value)} placeholder="Search anything you love…"/><button disabled={!input.trim()||!!loadingId} aria-label="Begin exploring">{loadingId?"···":"Explore ↗"}</button></form><button type="button" className="hero-surprise" disabled={!!loadingId} onClick={()=>{const pick=EXAMPLES[Math.floor(Math.random()*EXAMPLES.length)];setInput(pick.name);discover({text:pick.name,preferType:pick.prefer,...(pick.entityId?{entityId:pick.entityId,name:pick.name,entityType:pick.prefer,externalSource:pick.externalSource,externalId:pick.externalId}:{})})}}><Sparkles aria-hidden="true"/><span>Surprise me</span></button></div><div className="home-suggestions" aria-label="Suggested starting points"><span>Try</span>{EXAMPLES.slice(0,6).map(example=><button type="button" key={example.name} disabled={!!loadingId} style={{"--suggestion-tone":example.tone} as CSSProperties} onClick={()=>{setInput(example.name);discover({text:example.name,preferType:example.prefer,...(example.entityId?{entityId:example.entityId,name:example.name,entityType:example.prefer,externalSource:example.externalSource,externalId:example.externalId}:{})})}}><i aria-hidden="true">{example.icon}</i><span>{example.name}</span></button>)}</div>{recoveryPanel()}</div>:<div className={`seed-card ${root.image?"has-image":""}`} style={{left:WORLD.cx,top:WORLD.cy,"--node-accent":nodeAccents[root.id]||stableAccent(root.image||root.name),...(root.image?{backgroundImage:`url("${qlooImage(root.image,640)}")`}:{})} as CSSProperties} role="img" aria-label={`Starting interest: ${root.name}`}><span className="root-shade"><strong>{root.name}</strong><small>{root.type}</small></span></div>}
