     <section className={inspectorSection==="evidence"?"disclosure open":"disclosure"}><button type="button" className="disclosure-trigger" aria-expanded={inspectorSection==="evidence"} onClick={()=>{setInspectorSection(current=>current==="evidence"?null:"evidence");setSheetSize("full")}}><span>Connection details</span><b>{selected.affinity?`${Math.round(selected.affinity*100)}%`:"Verified"}</b><i aria-hidden="true"><ChevronDown/></i></button>{inspectorSection==="evidence"&&<div className="qloo-evidence"><div className="affinity-block"><div className="affinity-ring" style={{"--score":`${Math.round((selected.affinity??0)*100)*3.6}deg`} as CSSProperties}><strong>{selected.affinity?Math.round(selected.affinity*100):"✓"}<small>{selected.affinity?"%":""}</small></strong></div><div><span>{selected.relation?"Recorded relationship":"Audience affinity"}</span><b>{selected.relation?selected.relation:"Qloo connection strength"}</b><small>{selected.relation?"Factual connection resolved through Wikidata.":"Returned by Qloo Insights."}</small></div></div><dl className="evidence-ledger">{!!selected.tags?.length&&<div><dt>Tags</dt><dd>{selected.tags.slice(0,5).join(", ")}</dd></div>}<div><dt>Connected from</dt><dd>{selected.seedName}</dd></div><div><dt>Method</dt><dd>{selected.relation?"Direct knowledge graph":`Qloo Insights · ${selected.queryType}`}</dd></div><div><dt>Entity</dt><dd title={selected.id}>{selected.id.slice(0,8)}…{selected.id.slice(-5)}</dd></div></dl></div>}</section>
